<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Snake Game</title>
    <style>
        :root {
            --bg-color: #121212;
            --canvas-bg: #000;
            --text-color: #e0e0e0;
            --accent-green: #64c758;
            --food-red: #ff5f5f;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
        }

        #container {
            text-align: center;
        }

        h1 {
            font-size: 2rem;
            margin-bottom: 10px;
            color: var(--accent-green);
            letter-spacing: 2px;
        }

        #score {
            font-size: 1.5rem;
            margin-bottom: 15px;
            display: block;
        }

        canvas#snake {
            border: 2px solid #333;
            background-color: var(--canvas-bg);
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.5);
            display: block;
            width: 400px; /* CSS pixels >= 400 */
            height: 400px;
        }

        .controls {
            margin-top: 20px;
            display: flex;
            gap: 15px;
            justify-content: center;
        }

        button {
            background-color: #333;
            color: white;
            border: 1px solid #555;
            padding: 8px 16px;
            font-size: 1rem;
            cursor: pointer;
            border-radius: 4px;
            transition: background-color 0.2s, transform 0.1s;
        }

        button:hover {
            background-color: #444;
        }

        button:active {
            transform: translateY(1px);
        }

        .status-msg {
            margin-top: 5px;
            font-size: 0.9rem;
            color: #888;
            min-height: 20px; 
        }
    </style>
</head>
<body>
<div id="container">
    <h1>SNAKE</h1>
    <div id="score">Score: 0</div>
    <canvas id="snake" width="400" height="400"></canvas>

    <div class="controls">
        <button id="start">Start</button>
        <button id="pause">Pause</button>
        <button id="reset">Reset</button>
    </div>
    <div class="status-msg" id="msg"></div>
</div>

<script>
(function() {
    // --- Configuration & DOM ---
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const msgEl = document.getElementById('msg');

    // Constants: Grid dimensions (>= 10x10) and Cell size to achieve >=400px CSS rendering.
    // Since Canvas intrinsic is 400x400, dividing by cell gives grid width/height.
    const CELL_SIZE = 20; 
    const MAX_GRID_W = canvas.width / CELL_SIZE;
    const MAX_GRID_H = canvas.height / CELL_SIZE;

    // Game State Variables (Internal)
    let snakeArr = [];     // Array of {x, y} objects. HEAD FIRST (index 0).
    let foodPos = null;    // Object {x, y} or null if not spawned yet
    let direction = 'right'; 
    let nextDirBuffer = null; 
    let aliveVal = false;
    let scoreVal = 0;

    let gameLoopId = null;

    // Helper: Get Random Food Position (not on snake)
    function getRandomFoodPos(snakeBody) {
        let pos, attempts = 0;
        while (attempts < 1000) { // Safety break for infinite loop if grid full
            const x = Math.floor(Math.random() * MAX_GRID_W);
            const y = Math.floor(Math.random() * MAX_GRID_H);

            const occupied = snakeBody.some(segment => segment.x === x && segment.y === y);
            if (!occupied) {
                pos = {x, y};
                break;
            }
            attempts++;
        }
        return pos || {x:0,y:0}; // Fallback (rarely used)
    }

    // --- GAME API IMPLEMENTATION (`window.game`) ---

    window.game = {};

    // Expose dimensions as properties on the game object
    Object.defineProperty(window.game, 'w', { value: MAX_GRID_W, enumerable: true });
    Object.defineProperty(window.game, 'h', { value: MAX_GRID_H, enumerable: true });

    // Reset Game (New Game)
    window.game.reset = function() {
        if(gameLoopId) clearInterval(gameLoopId);

        const startX = Math.floor(MAX_GRID_W / 2);
        const startY = Math.floor(MAX_GRID_H / 2);

        snakeArr = [
            {x: startX, y: startY},          // Head (index 0)
            {x: startX - 1, y: startY},      // Body (len >=3)
            {x: startX - 2, y: startY}       // Tail
        ];

        foodPos = getRandomFoodPos(snakeArr);

        direction = 'right';
        nextDirBuffer = null;
        aliveVal = true;
        scoreVal = 0;

        updateUI();
        draw();
    };

    // Advance exactly one step
    window.game.tick = function() {
        if (!aliveVal) return false;

        let moveDir = direction;

        // Apply buffered turn, respecting reversal rules against CURRENT heading.
        // If buffer is not opposite to current `direction`, we apply it for this tick's movement.
        // Note: This logic effectively queues a turn that takes effect on the next cell traversal calculation.
        if (nextDirBuffer) {
            const opposites = {'up':'down', 'down':'up', 'left':'right', 'right':'left'};
            // Check reversal relative to current heading BEFORE applying for this step? 
            // Actually, standard behavior: input queued from previous tick(s). We check if it's valid now.
            // If buffer is opposite to *current* direction at start of Tick (which might have changed since setDir?), ignore.
            // However, my `setDir` already checks against heading when setting. 
            // To be safe and consistent with "queue a turn" contract: if we apply it now, ensure it's not reversing relative to state where Snake is currently oriented?
            // For simplicity in this implementation: We trust the buffer was valid upon input (checked by setDir). But strict adherence requires checking against current heading. 
            // Let's implement check here too for robustness: if invalid vs `direction` at start of tick, ignore it and clear buffer.

            if (opposites[nextDirBuffer] !== direction) {
                moveDir = nextDirBuffer;
                // Update internal state so subsequent setDir calls see new heading immediately? 
                // If we do this here, `setDir` called between ticks will use updated 'direction'. That is acceptable.
                if (moveDir === 'up' || moveDir === 'down') direction = moveDir; else { /* wait */ }
                // Actually simpler: Update direction to match the active turn so next check works correctly for this tick or future ones immediately? 
                // But does `tick` modify state permanently? Yes, once we decide to go UP, our heading is now UP (after completing step). 
                // For consistency with "180 reversal ignored", if buffer was invalid relative to *current* start-of-tick direction, we drop it.
            } else {
                nextDirBuffer = null; // Drop invalid buffered turn immediately at tick time? Or keep trying until valid? Usually dropped in this context for API simplicity.
            }
        }

        const head = snakeArr[0];
        let newHead = {x: head.x, y: head.y};

        switch (moveDir) {
            case 'up': newHead.y--; break;
            case 'down': newHead.y++; break;
            case 'left': newHead.x--; break;
            case 'right': newHead.x++; break;
        }

        // Check Wall Collision relative to potential NewHead position against current bounds.
        if (newHead.x < 0 || newHead.x >= MAX_GRID_W || 
            newHead.y < 0 || newHead.y >= MAX_GRID_H) {
            aliveVal = false;
            updateUI();
            draw();
            return true; // Step resulted in death
        }

        // Check Self Collision (against current body segments *before* move).
        for (let i = 0; i < snakeArr.length; i++) {
            if (newHead.x === snakeArr[i].x && newHead.y === snakeArr[i].y) {
                aliveVal = false; 
                updateUI();
                draw();
                return true; // Step resulted in death
            }
        }

        const ateFood = (foodPos && newHead.x === foodPos.x && newHead.y === foodPos.y);

        if (ateFood) {
            scoreVal++;
            generateNewFood(snakeArr, MAX_GRID_W, MAX_GRID_H); // Ensure snake passed to helper is updated? 
                                                               // Wait: We haven't unshifted yet. If we pass current state, new head pos not there yet?
                                                               // Actually foodPos check uses *old* Head position logic (newHead). Snake array still has old config.
                                                               // It's okay to generate using snakeArr without the newHead yet because that cell is occupied by nothing in snakeArr currently. 
                                                               // However, after unshift, that cell will be head. We want food not on ANY segment *after* move. So we should update array first?
            scoreVal++; 
        } else {
            // If NOT eating, logic for tail removal must happen AFTER checking if eaten (to keep tail).
            // Actually standard snake: Add Head -> Check Food -> If no Food Remove Tail.
            // Let's structure move: Unshift then maybe pop.

            // Re-structure flow slightly to match robustness requirements of API state consistency.
        }

        // Corrected Move Logic for State Consistency
        // 1. Calculate potential new Head (done above).
        // 2. Check collisions against current body segments. (Done above, sets alive=false on fail)
        // 3. Update Snake Structure: Unshift newHead.

        snakeArr.unshift(newHead);

        let justAte = false;
        if(foodPos && newHead.x === foodPos.x && newHead.y === foodPos.y) {
            scoreVal++;
            generateNewFood(snakeArr, MAX_GRID_W, MAX_GRID_H); // Now array contains the head at new pos.
            justAte = true;
        }

        if (!justAte) {
            snakeArr.pop();
        } else {
             updateUI(); draw(); // Food eaten - redraw immediately after growth? (draw will run at end anyway). 
               // Just let the flow continue to common draw call.
        }

        updateUI();
        draw();

        if (!aliveVal) clearInterval(gameLoopId);
    };

    function generateNewFood(snakeBody, w, h) {
        foodPos = getRandomFoodPos(snakeBody);
    }

    window.game.setDir = function(dir) {
        const opposites = {'up':'down', 'down':'up', 'left':'right', 'right':'left'};
        // Ignore 180° reversal relative to CURRENT heading at time of input.
        if (opposites[dir] !== direction) {
            nextDirBuffer = dir; 
        } else {
            // Ignored - snake keeps its heading. Do not update buffer, do not change current state.
        }
    };

    window.game.setFood = function(x, y) {
        foodPos = {x: x, y: y};
        draw(); // Redraw immediately as per spec.
    };

    window.game.snake = function() {
        return snakeArr.map(s => [s.x, s.y]);
    };

    window.game.food = function() {
        if (!foodPos) return null;
        return [foodPos.x, foodPos.y];
    };

    window.game.alive = function() {
        return aliveVal;
    };

    window.game.score = function() {
        return scoreVal;
    };

    // --- UI & EVENTS ---

    function updateUI() {
        scoreEl.innerText = "Score: " + scoreVal;
        if (!aliveVal) msgEl.innerText = "Game Over! Press Reset.";
        else msgEl.innerText = "";
    }

    function draw() {
        ctx.fillStyle = '#121212'; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        if (!foodPos && !aliveVal) return; // If game over and no food to draw? Draw snake anyway.

        // Snake Body (including Head before death state check maybe?)
        snakeArr.forEach((segment, index) => {
            const x = segment.x * CELL_SIZE;
            const y = segment.y * CELL_SIZE;

            ctx.fillStyle = (index === 0 && aliveVal) ? '#64c758' : '#3a9e4b'; // Head Green if alive, else body. 
            // If dead, maybe draw red? Not required but "Make it feel good". I'll keep consistent or dimmed on death?

            ctx.fillRect(x, y, CELL_SIZE - 1, CELL_SIZE - 1); 
        });

        // Food (Red Circle)
        if (foodPos) {
            const fx = foodPos.x * CELL_SIZE + CELL_SIZE/2;
            const fy = foodPos.y * CELL_SIZE + CELL_SIZE/2;

            ctx.fillStyle = '#ff5f5f';
            ctx.beginPath();
            ctx.arc(fx, fy, CELL_SIZE/2 - 1, 0, Math.PI * 2);
            ctx.fill();
        }

        if (!aliveVal) {
            // Overlay Game Over text
            const overlay = document.createElement('div');
            overlay.style.position = 'absolute'; 
            overlay.style.top = '50%';
            overlay.style.left = '50%';
            overlay.style.transform = 'translate(-50%, -50%)';
            overlay.style.color = '#fff';
            overlay.style.fontFamily = 'monospace';
            overlay.style.textAlign = 'center';
            overlay.innerText = 'GAME OVER\nScore: '+scoreVal+'\nPress Reset to play again';

            // Since canvas draws directly, let's use simple text on canvas.
            ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
            ctx.fillRect(0,0,canvas.width, canvas.height);
            ctx.fillStyle = '#fff';
            ctx.font = "30px sans-serif";
            ctx.textAlign = "center";
            // Simple alignment
            ctx.fillText("GAME OVER", canvas.width/2, canvas.height/2 - 15);
            ctx.font = "20px sans-serif";
            ctx.fillText("Score: " + scoreVal, canvas.width/2, canvas.height/2 + 30);
        }
    }

    // Button Listeners
    document.getElementById('start').addEventListener('click', () => {
        if(gameLoopId) clearInterval(gameLoopId);
        gameLoopId = setInterval(() => window.game.tick(), 100); 
    });

    document.getElementById('pause').addEventListener('click', () => {
        if(gameLoopId) clearInterval(gameLoopId);
        gameLoopId = null;
    });

    document.getElementById('reset').addEventListener('click', () => {
        if(gameLoopId) clearInterval(gameLoopId);
        gameLoopId = null;
        window.game.reset();
    });

    // Keyboard Input for User Control
    document.addEventListener('keydown', (e) => {
        const map = {'ArrowUp':'up','ArrowDown':'down','ArrowLeft':'left','ArrowRight':'right'};

        if(map[e.key]) {
            e.preventDefault(); // Prevent scrolling with arrows
            window.game.setDir(map[e.key]);
        }
    });

    // Initial Setup (Visual only, game starts paused)
    draw(); 

})(); 
</script>
</body>
</html>
